def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    if not cwd.startswith('/') or (cwd != '/' and cwd.endswith('/')):
        return None

    link_count = 0

    # Start with cwd if path is relative
    if path.startswith('/'):
        current = '/'
        components = path.split('/')[1:]
    else:
        current = cwd
        components = path.split('/')

    i = 0
    while i < len(components):
        comp = components[i]

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            i += 1
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            i += 1
            continue

        # Append the component
        if current == '/':
            current = '/' + comp
        else:
            current = current + '/' + comp

        # Check if current is a symlink
        if current in links:
            link_count += 1
            if link_count > 8:
                return None

            target = links[current]

            # Remaining components after this one
            remaining = components[i+1:]

            # Parse the target
            if target.startswith('/'):
                # Absolute target
                current = '/'
                target_components = target.split('/')[1:]
            else:
                # Relative target - resolve relative to the directory containing the link
                if current != '/':
                    current = current.rsplit('/', 1)[0]
                    if current == '':
                        current = '/'
                target_components = target.split('/')

            # Continue resolution with target components and remaining components
            components = target_components + remaining
            i = 0
            continue

        i += 1

    # Return the result without trailing slash (except for '/')
    if current == '/':
        return '/'
    return current

